const recipes={
 opening:{observation:'Gündüzden geceye aynı aerial üzerinde ışık değişiyor; kimlik okunur kalıyor. Açılış, sonraki gündüz kamera sahnesinden farklı bir ışık durumunda bitiyor.',action:'Işık değişimini koru; ilk kamera hareketine geçerken aynı gün ışığı ve aynı ev odağını kullan. Başlığın çıkışını kamera başlamadan tamamla.',avoid:'Kayıt hero açıkken başlar. Yükleme ekranı veya ilk siyah örtünün davranışı bu kesitten puanlanamaz.',refs:[R('likova','hero','Beyaz kimlik yüzeyi ayrılırken bina alttan görünür: kimliği kamera girişinden önce bitirme sırasını al; basamak biçimini kopyalama.'),R('era','hero-dive','Başlığın kameradan farklı hızla çıkması, görüntü hedefi ile kimliği ayırıyor. Angora’da aynı ritmi daha küçük bir mesafeyle kullan.')]},
 camera:{observation:'Bina ve havuz çevresinde kamera yeri değişiyor; varışta sahne başlığı ve açıklama geliyor. Üç durak farklı mekânsal bilgi taşıyor.',action:'Kamera rotasını koru. Metni varışta aç, bir sonraki hareketten önce kapat; durak etiketini görüntüyle aynı anda güncelle. Gündüz kadrajlarını tek bir renk dengesinde tut.',avoid:'Klip süresi kullanıcı beklemesini içerir; bu kayıttan tek wheel hareketi sayısı veya input gecikmesi ölçülmez.',refs:[R('likova','model','Kamera durumuyla bilgi değişimi birlikte yönetiliyor. Alınacak şey model estetiği değil, bir açı = bir bilgi ilişkisi.'),R('era','hero-dive','Yaklaşmanın belirli bir mimari hedefi var. Angora’daki her kamera parçasının da ev/havuz odağı sabit kalmalı.')]},
 heroExit:{observation:'Life opens outside kadrajı üstte ince bir şeride dönüşürken kırık beyaz metin bölümü açılıyor. Görüntünün tam eve ait son duruşu okunmadan iki bölümün ritmi değişiyor.',action:'Son kamera karesini önce tut. Görüntü ve görünür pencereyi aynı ev odağı çevresinde birlikte küçült; yeni başlığı bunun ardından aç. Alternatif: yeni kâğıt yüzeyi önceki görüntüyü tek yönde devralsın.',avoid:'ERA’nın kemerini veya Likova’nın basamağını Angora’ya doğrudan taşıma. Bu eşiğin sorunu dekor eksikliği değil, son kadrajın erken kaybolması.',refs:[R('era','architecture-exit','Fotoğrafın geri çekilmesi bilgi yüzeyiyle aynı kurgu içinde. Pencere ile içindeki evin oranını birlikte yönetme ilkesini al.'),R('likova','video-story','Video akarken yeni metin yüzeyi görüntüyü devralıyor. Ani bölüm değişimi yerine önce gelen yüzeyi tanıtma sırası uygun.')]},
 intro:{observation:'Serif ana cümle, açıklama ve dört alan bilgisi sakin kâğıt zemin üzerinde sıralanıyor. Uzun açıklama ile küçük ölçü altyazılarının ritmi farklı.',action:'Bu bilgi molasını koru. Ana cümle → paragraf → ölçüler sırasını netleştir; alan altyazılarına görsel vurgudan bağımsız okunur boyut ver.',avoid:'Sayı saydırma, dönen metin veya ek maske gerekmiyor; bu bölümün görevi evin ölçeğini açıklamak.',refs:[R('era','residence-type','Görsel, kat adı ve ölçüler aynı bilgi grubunda. Angora’da da 500/400/900 bilgisini kendi açıklamasıyla birlikte tut.')]},
 arrival:{observation:'Sokak cephesi fotoğrafı ve A quieter arrival metni aynı konuyu anlatıyor. Fotoğrafın öncesinde ve sonrasında geniş kâğıt alan kalıyor.',action:'Cadde girişini tam okunur kadrajla göster; fotoğrafı hafif büyüten paralaksı yalnız bu mekânsal bilgiye hizmet edecek kadar kullan. Caption fotoğrafla birlikte hareket etsin.',avoid:'Aerial ile sokak kapısı fotoğrafını aynı gelişigüzel kadrajda değiştirerek giriş yönünü belirsizleştirme.',refs:[R('era','interior-columns','Fotoğraf ve açıklama aynı bloktayken kolonlar farklı hızda ilerliyor. Bağımsız caption yerine bağlı bir fotoğraf–metin çifti kullan.'),R('likova','paired-images','Cephe detaylarının kendi kadrajları korunuyor. Angora’da tek güçlü sokak görünümü yeterli; ikinci fotoğraf sırf efekt için eklenmemeli.')]},
 rooms:{observation:'Yatak odası görselleri aynı oda hikâyesini farklı katlarla açıyor. Desktop’ta düşey fotoğraf sütunu, mobilde tek fotoğraf penceresi görülüyor.',action:'Oda fotoğraflarının ölçeğini ve birbirine bağlı caption’larını koru. Son fotoğrafın alt kenarı, bahçe sahnesinin ilk durumunu haber versin.',avoid:'Üç ayrı oda resmini ERA’daki birleşme gibi tek kesintisiz görüntüymüşçesine birleştirme.',refs:[R('era','interior-columns','İç mekân fotoğraflarının farklı hizalarda ilerlemesi Angora’nın oda sırasına uygun. Görsel/caption bağı korunmalı.'),R('era','interior-gallery','Son fotoğrafın çıkışında sonraki mimari sahnenin ilk durumu görünüyor. Bahçe girişini bu devamlılıkla kur.')]},
 roomMove:{observation:'Bir yatak odası çıkarken sıradaki odanın fotoğrafı aynı akıştan giriyor. Başlık yerini büyük ölçüde koruyor; oda etiketi resmin altında kalıyor.',action:'Yönü ve ortak fotoğraf genişliğini koru. Caption’ı kendi fotoğrafından koparma; ortadaki iki yarım fotoğrafı okuma durağı yapma.',avoid:'Her oda için tam ekran kamera efekti gerekmiyor; mevcut sütun hareketi bu içerik için yeterli.',refs:[R('era','detail-gallery','Fotoğraf sütunu ilerlerken konut bilgisi sabit okunuyor. Angora’nın oda sırasına doğrudan uyan hiyerarşi.'),R('era','interior-columns','Fotoğraf ve caption aynı birim olarak ilerlemeli. Hareket farkı okuma ilişkisini bozmamalı.')]},
 gardenEntry:{observation:'Kâğıt zemindeki oda sahnesinin altından havuzlu dış görünüm ve More sky. More time. başlığı açılıyor. Dış mekân yeni, belirgin bir ölçek kazanıyor.',action:'Fotoğrafın ilk görünen kenarını bir önceki bölümde göster; tam ekranı devralınca bahçe metnini aç. Başlık, fotoğraf tam kadraja oturana kadar üst sınıra sıkışmasın.',avoid:'İki fotoğrafın birleşme efekti bu geçişe uygun değil; oda ile aerial aynı kamera sahnesi değil.',refs:[R('era','closing-cta','Geniş teras ve büyük başlık tek sahne olarak alttan yerleşiyor. Angora’nın havuz girişinde aynı görüntü-önce/metin-sonra sırası uygun.'),R('likova','architecture','Görsel büyürken bilgi yüzeyi kendi eşiğini koruyor. Önceki odadan bahçeye geçişin ölçek farkını bu ilkeyle yönet.')]},
 gardenChange:{observation:'Havuz, kapalı teras ve bahçe aynı tam ekran alanında değişiyor; ilgili kısa metin ve seçili dış mekân etiketi de değişiyor.',action:'Bu üç ayrı yaşam durağını koru. Yeni görüntü hazırken metni güncelle; önceki caption yeni fotoğrafın üzerinde beklemesin. Bahçe fotoğrafının yeşil tonlarını diğer ikisiyle eşitle.',avoid:'Diyagonal kesim, dekoratif çizgi veya tekrar kamera dalışı ekleme; mekân değişimini fotoğraf ve bilgi birlikte anlatıyor.',refs:[R('era','amenity-tabs','Seçili öğe, açıklama ve fotoğraf aynı durum değişimini taşıyor. Angora’da bu senkronu koru; ERA’daki eğimli maskeyi alma.'),R('likova','lifestyle','Yaşam resmi değişimi yeni bir bilgi getiriyor. Fotoğrafı aynı pencerede değiştirmek burada yeterli bir hareket.')]},
 gardenReverse:{observation:'Bahçe sahnesi geri ziyaret ediliyor; önceki fotoğraf/metin durumları yeniden görünüyor. Geri akışın yönü, ileri sıraya göre ters okunuyor.',action:'Aynı sahne durumuna geri dön; her geri gelişte giriş animasyonunu baştan kurma. Seçili dış mekân ile caption’ın önceki durumunu birlikte geri yükle.',avoid:'Kayıttaki geri dönüş, wheel kilidinin her cihazda kusursuz olduğunu kanıtlamaz. Bu not yalnız görünen geri akış içindir.',refs:[R('era','footer-reverse','Geri harekette önceki görüntü, aynı kurgu ters okunarak geri geliyor. Angora’da da reset yerine durum sürekliliği uygun.'),R('likova','video-story','İleri ve geri katmanlar aynı film bağlamına dönüyor. Fotoğraf geri ziyaretinde yeni bir kararma ekleme.')]},
 gardenExit:{observation:'Yeşil dış mekân fotoğrafından Come together. Feel at home. kâğıt bölümüne düşey geçiliyor. İç mekân başlığı ve ilk salon resmi son bahçe kadrajının ardından geliyor.',action:'Bahçenin çıkış kenarına iç bölümün kâğıt yüzeyini önceden getir. Önce bölüm rengini, ardından salon fotoğrafını ve başlığı okut; renk ve metni tek anda değiştirme.',avoid:'Son dış fotoğrafı gereksiz bir boş kutuya küçültme. Yeni iç mekân yüzeyi yeterli anlatı eşiği sağlar.',refs:[R('era','interior-arch','Önceki amenity fotoğrafının üstünde yeni iç mekân yüzeyi görünür. Kavis şeklinden önce bu yüzey devralma sırasını al.'),R('likova','architect-quote','Bilgi kartı dış cephe ile lobi arasında anlatım köprüsü oluyor. Bahçe → salon bağlantısında küçük bir bilgi eşiği işe yarar.')]},
 inside:{observation:'Salonun ana fotoğrafı, küçük ikinci açı ve açıklama aynı iç mekân bölümünde okunuyor. Fotoğraf seçimi içerikle uyumlu.',action:'İki fotoğrafın farklı görevini koru: geniş görünüm mekânı, küçük resim ikinci açıyı açıklasın. Metin ile büyük fotoğrafın gelişini birbirine yakın tut.',avoid:'Büyük salon görüntüsünün üzerine sırf malzeme referansı için kayan küre, panel veya yapay 3D parçalar ekleme.',refs:[R('era','interior-columns','Büyük ve küçük fotoğrafların farklı hizalarda okunması bu bölümün ölçeğine uygun.'),R('likova','lobby','Ana mekân fotoğrafı ve ardından gelen ayrıntılar aynı bilgi sırasını koruyor. Salon → ikinci açı sırasını bu sadelikle sürdür.')]},
 private:{observation:'Salonun ikinci açısı çıktıktan sonra özel yatak odası ve giyinme alanı geliyor. Ortadaki kâğıt boşluğu yeni odanın girişini uzatıyor.',action:'Yeni oda başlığını önceki fotoğrafın sonuyla yakınlaştır. Özel alanın büyük resmi → giyinme detayı → mutfak sırasını koru; geniş boşluğu daha kısa bir soluklanma alanına çevir.',avoid:'Salon ile yatak odasının görüntülerini aynı mimari sahneymiş gibi eritme; iki odanın kimliği ayrı kalmalı.',refs:[R('era','interior-columns','Farklı fotoğraf büyüklükleri ve açıklamalar tek akışta kalabiliyor. Boşlukları bu fotoğraf ilişkisi belirlesin.')]},
 kitchenEntry:{observation:'Yatak odasının kâğıt zemini yeşil mutfak bölümüne geçiyor. Başlık ve ilk mutfak fotoğrafı yeni renk sahnesini kuruyor.',action:'Yeşil yüzeyi ilk fotoğraftan hemen önce tanıt; başlığı fotoğrafla yakın zamanda aç. Yeni bölümün ilk kadrajında üstte kalan eski yatak odası şeridini kısa tut.',avoid:'Her renk değişiminde aynı dev maske şakasını tekrarlama. Bu ara geçiş sakin bir yüzey değişimi olarak kalabilir.',refs:[R('likova','offices','Video/önceki içerik, koyu çalışma alanı yüzeyi ve mekân fotoğrafı sırayla açılıyor. Alınacak şey bu net sıra.'),R('era','interior-arch','Yeni bölümün rengi başlığa zemin oluşturuyor. Angora’da bunu düz ve sade bir eşikle yap.')]},
 kitchenMove:{observation:'Ana mutfak, bahçe katı mutfağı ve çatı altındaki küçük mutfak farklı fotoğraflarla gösteriliyor. Her birinin caption’ı kendi fotoğrafını açıklıyor.',action:'Üç fotoğrafı koru; bu farklı kullanım bilgisidir. Son mutfak resmi çıktıktan sonra kat modelinin ilk karesini göster; fotoğraf dizisini erken kesme.',avoid:'Üç mutfağı tek resimmiş gibi morph etme. Ortak genişlik ve düzenli aralık bu sahneyi zaten birleştiriyor.',refs:[R('era','detail-gallery','Bir fotoğraf sütununda mekân bilgisi korunuyor. Mutfakların farklılığını okutan bir ritim.'),R('likova','infrastructure','Her yeni görüntünün kendi kullanım açıklaması var. Çok görüntü kullanmayı haklı çıkaran şey içerik değişimi; şekilli maskeler değil.')]},
 isoEntry:{observation:'Yeşil mutfak sahnesinin ardından beyaz zemin üzerinde garden-level isometrik model açılıyor. Teknik anlatı ile fotoğraf anlatısı belirgin biçimde ayrılıyor.',action:'Son mutfak fotoğrafının altından aynı beyaz teknik yüzeyi getir. Önce bütün modelin sınırlarını göster, sonra Garden level bilgisi aç; çevre kırpığını ve model ölçeğini tüm katlarda eşitle.',avoid:'İsometriyi fotoğraf gibi cover ile kırpma. Evin tabanını, havuzu ve sınırı model sunumunun bütününde koru.',refs:[R('likova','master-plan','Beyaz teknik yüzey, bütün model ve 3D çağrısını tek sahnede topluyor. Angora’da modelin sınırlarını önce, kat açıklamasını ardından okutmak bu ilişkiden bir uyarlama.'),R('era','residence-type','Kat adı ve ölçü, modeli açıklayan bir grup olarak yerleşiyor; bağımsız süs animasyonu değil.')]},
 isoMove:{observation:'Model aynı isometrik yönde kalırken bir sonraki kat görünümü oluşuyor. Kat metni kısa süre düşük opasiteye inip yeni bilgiyle geri geliyor; model ve metin tam aynı anda yerleşmiyor.',action:'Geometrik dönüşümü koru. Eski metni hareket başında çıkar, yeni metni modelin son karesine bağla. Her katın bina merkezini ve ölçeğini sabit tut; sabit duruşta ek solma olmasın.',avoid:'Likova’daki orbit hareketini kat kesiti değişimine aynen uygulama. Burada yönü sabit tutmak katların ilişkisini anlatıyor.',refs:[R('likova','model','Kamera durumu ile sayısal bilgi birlikte değişiyor. Angora’da aynı senkron ilkesi kat/model metnine uygulanmalı.'),R('era','amenity-tabs','Görsel ve seçili bilgi tek durumdan yönetiliyor. Kat metnini modelden ayrı timer’larla geciktirme.')]},
 atlasEntry:{observation:'Isometrik akış attic durumunda biterken plan anlatısı Garden level ile yeniden başlıyor. Aynı katın isometrik ve plan karşılığı üzerinden bir bağlantı kurulmadan bölüm ve kat birlikte değişiyor.',action:'Önce seçili katı koru: attic iso → attic plan. Modeli planın üstten görünümüne yönlendir ya da ortak bina konturuyla sade bir dissolve kur. Garden’a dönmek ayrıca anlaşılır bir seçime bağlı olsun.',avoid:'Referanslarda birebir floor-to-plan morph yok. Bu öneri Likova’nın bütün model mantığı ile ERA’nın plan-bilgi hiyerarşisinden yapılan tasarım çıkarımıdır.',refs:[R('era','plan-detail','Seçilen plan, aynı konutun bilgisine bağlanıyor; seçim kimliği değişmiyor. Angora’da seçili kat korunmalı.'),R('likova','master-plan','Bütün modeli okunur tutan teknik eşik, plan geçişinin ön koşulu. Buradan rastgele kamera uçuşu alma.')]},
 atlasMove:{observation:'Plan ve ilgili fotoğraf yatay sırada bir sonraki kata geçiyor. Yeni katın kamera noktaları ve oda isimleri geliyor; hareket sırasında iki katın parçaları yan yana görünüyor.',action:'Tek yatay hareketi koru; eski plan+fotoğraf ve yeni plan+fotoğraf iki tam grup olarak kaysın. Son durumda kat adı, seçili kamera, fotoğraf ve alan bilgisini aynı anda sabitle.',avoid:'Konturları yeniden çizerek oluşturma, diyagonal bölme veya her pin için ayrı pop efekti ekleme. Öncelik teknik okunurluk.',refs:[R('era','horizontal','Fotoğraf ile başlık aynı gerçek yatay rayda ilerliyor. Plan+fotoğraf çifti bu rayın tek birimi olmalı.'),R('era','plan-detail','Plan ve oda/alan bilgisi birlikte okunuyor. Angora’nın teknik planını hareket süsünden daha fazla önemse.')]},
 cameraPoint:{observation:'Garden planında kamera 3 seçili; kahverengi pin ve alt fotoğraf düğmesindeki 3 aynı noktayı işaretliyor. Living room fotoğrafı bu seçime bağlı; bakış yönü küçük plan üzerinde çok silik kalıyor.',action:'Aktif pin, bakış konisi ve fotoğrafı aynı durumda tut. Aktif koni yüksek kontrastlı, diğerleri düşük opasiteli olsun; bütün pinleri aynı vurguya getirme.',avoid:'Kayıtta kamera 3’ün seçili hali görülür; pinler arasında seçim değişimi gösterilmez. Diğer tüm noktaların çalıştığı varsayılmadı.',refs:[R('era','pins','Her noktanın kendi bilgi kartı var. Angora’da kartın yerine gerçek oda fotoğrafı ve belirgin bakış yönü kullan.'),R('likova','map-tabs','Seçili vurgu ile bilgi aynı zeminde birlikte değişiyor; planın kendisi gereksiz yere oynamıyor.')]},
 returnIso:{observation:'Plan sahnesinden isometrik bölüme geri dönülüyor; görünüm yeniden Garden level’e geliyor. Teknik anlatının kat kimliği bu sıçramada devam etmiyor.',action:'Geri dönüşte seçili kat ve bina ölçeğini koru. Plan → aynı kat iso olarak aç; yeni kat ilerleyişini bundan sonra başlat. Scroll ve bölüm linki aynı hedef durumunu kullanmalı.',avoid:'Kayıt hangi input yolunun tetiklediğini her seferinde göstermiyor. Bunu kanıtlanmış wheel kilidi diye değil, görülen durum sıçraması olarak değerlendir.',refs:[R('era','footer-reverse','Geri dönüş aynı kompozisyonu yeniden kuruyor. Angora’nın kat kimliği de geriye giderken resetlenmemeli.'),R('likova','hero-return','Önceki kamera durumu geri gelirken aynı zemin ilişkisi sürüyor. Geri navigasyon da ileri kadar tasarlanmalı.')]},
 details:{observation:'Plan anlatısından dört pratik bilgiye ve merdiven fotoğrafına geçiliyor. Merdiven resmi dört katı birleştiren somut bir bağ kuruyor.',action:'Merdiven fotoğrafını teknik anlatının çıkışında biraz daha erken göster. Dört özellik metnini aynı hareketle yarışmadan okut; yeni bölüm başlığı görünür olduktan sonra küçük detayları aç.',avoid:'Teknik altyapı görüntüsü veya dekoratif çizgi eklemek gerekmiyor; mevcut merdiven bu evin gerçek bağlantısını anlatıyor.',refs:[R('likova','technology','Teknik bilgi ile onu açıklayan görüntünün eşleşmesi yararlı. Angora’da bunu gerçek merdiven/lift bilgisine indir.'),R('era','architecture-exit','Görüntüden bilgi alanına geçişte ortak bir yüzey korunuyor. Plan çıkışını aynı okunur teknik ritimle kur.')]},
 neighbourhood:{observation:'Merdiven fotoğrafının ardından villa mahallesinin geniş görünümü ve A quieter side of the city metni geliyor. Ölçek ev içinden çevreye açılıyor.',action:'Mahalle resmini hafif ölçek/paralaksla aç; villa ve sokak dokusunu kadrajda koru. Metni fotoğrafın gelişinden sonra kısa bir aralıkla getir. Sadece dekor için üç ayrı yön kullanma.',avoid:'Buradaki aerial, evin sokak girişini gösteren fotoğrafın yerine geçmez. Konum bilgisi ayrı kalmalı.',refs:[R('era','aerial','Geniş çevre görüntüsü bir ölçek açılımı sağlıyor. Bulut efekti yerine Angora’nın mevcut aerial kadrajını kullan.'),R('likova','location-collage','Modelden gerçek çevreye geçerken görüntü ile konum metni eşleşiyor. Ev → mahalle bağı bu şekilde kurulmalı.')]},
 map:{observation:'Çevre haritası ve yeşil yaşam kartı açılıyor; Villa/Angora sınırı ve renkli noktalar gösteriliyor. Çok sayıda noktanın işlevi küçük alttaki legend’e bağlı.',action:'Harita girişini sakin tut. Ev işaretini ve dashed sınırı birbirinden ayır; legend haritanın hemen altında yeterli boyutta dursun. Kartı konumun üstüne taşırken temel ev işaretini örtme.',avoid:'Yeni uçan pin veya bütün noktalar için etiket gerekmiyor. Görüntü statik harita; kayıt interaktif harita yeteneğini kanıtlamaz.',refs:[R('likova','map-entry','Harita ve açıklama kartı iki ayrı okunur yüzey. Angora’nın haritasında da bilgi katmanlarını bu hiyerarşiyle kur.'),R('era','route','Rota/yer bilgisi grafiğe bağlı kalıyor. Angora’daki dashed sınırın açıklaması da haritadan kopmamalı.')]},
 journalEntry:{observation:'Harita çıktıktan sonra Angora Journal açılıyor. Sonbahar mahalle fotoğrafı ve spor alanı fotoğrafı iki ayrı yaşam başlığına bağlanıyor; ikisi de kayıtta görünür.',action:'Bu iki fotoğrafı koru. İlkini soldan, ikincisini daha düşük bir düşey hizadan yumuşakça getir; caption kendi fotoğrafına bağlı kalsın. İkinci resmi ilkinden sonra okut.',avoid:'İki görüntü aynı panorama değil; ERA’nın iki pencere birleşmesi burada yanıltıcı olur. Görselleri birleştirme.',refs:[R('era','interior-columns','İki fotoğraf farklı hizalarla derinlik kuruyor ama açıklamalar kendi fotoğraflarıyla kalıyor. Journal için uygun hareket seçkisi.'),R('likova','lifestyle','Yaşam görseli, kendisine ait açıklamayı taşıyor. Fotoğraf seçiminin gerekçesi hareketten daha önemli.')]},
 journal:{observation:'Mahalle yaşamı ve spor/ortak alan fotoğraflarının altında ilgili açıklamalar okunuyor. Ardından Ankara kültür linkleri ve küçük kaynak notu geliyor.',action:'Fotoğraf–caption ilişkisini ve iki farklı yaşam konusunu koru. Link satırı ile kaynak notuna aynı okuma hızı verme; kaynak notu görünür ama geri planda kalsın.',avoid:'Bilkent/CerModern için bu kayıtta olmayan bir görsel veya kamera geçişi varmış gibi puanlama; görülen kısım metin ve linklerden oluşuyor.',refs:[R('likova','infrastructure','Farklı yaşam olanaklarının her birine kendi fotoğrafı ve açıklaması bağlanıyor. Angora’daki iki başlık bu ilkeyle zaten doğru yönde.'),R('era','interior-columns','Fotoğraf ve açıklama aynı blokta kaldığında farklı hızlar okumayı bölmez. Mevcut journal düzenini bu sınırda tut.')]},
 galleryEntry:{observation:'Yaşam anlatısı bittikten sonra seçilmiş ev fotoğrafları aynı yeşil zeminde açılıyor. Take a closer look başlığıyla dış yaşamdan tekrar evin içine dönülüyor.',action:'Başlığı ve ilk iki seçilmiş fotoğrafı tek giriş olarak okut. Yeşil zemini koru; yeni bir büyük renk maskesi gerekmiyor. Kaydırma yönünü ancak galeri tam yerleşince yataya çevir.',avoid:'Kütüphaneyi kullanmak için bütün fotoğrafları dökme; seçilmiş sekiz görüntü bir ikinci özet turu olmalı.',refs:[R('likova','lobby','Ana mekân bilgisi galerinin ilk karesine bağlanıyor. Angora’da journal çıkışı ile ilk ev fotoğrafı arasında aynı kısa eşik uygun.'),R('era','interior-gallery','Galerinin başlığı ve kontrolleri fotoğrafla aynı sahneye ait. Girişte ayrı ayrı uçan öğeler kullanma.')]},
 gallery:{observation:'Seçilen fotoğraflar yatay rayda ilerliyor; oda adı ve sayaç fotoğraflarla birlikte okunuyor. Her fotoğraf yeni bir mekân gösteriyor.',action:'Yatay akışı koru. Son fotoğraf tam okunmadan galeri pin’ini bırakma; rayın bitişini contact bölümüne tek bir düşey devirle bağla. Caption ve sayaç değişimini aynı aktif fotoğrafa bağla.',avoid:'ERA’nın konum hikâyesindeki metin ölçeğini buraya taşıma. Bu sahne ayrıntılı fotoğraf incelemesi; başlık geri planda kalmalı.',refs:[R('era','horizontal','Düşey kaydırmanın gerçek yatay rayı ilerletmesi bu galeri için uygun. Son hedefin mesafesi içerik genişliğiyle belirlenmeli.'),R('likova','lobby','Galeride resim sırası ile küçük kontrol bilgileri aynı sahnede kalıyor. Angora için daha sade bir eşleşme.')]},
 lightbox:{observation:'Galerideki sitting-area fotoğrafı tek büyük pencerede açılıyor; yeşil çevre ve Close kontrolü kalıyor. Ardından aynı galeri rayına geri dönülüyor.',action:'Seçilen fotoğrafın kimliğini ve raydaki konumunu koru. Açılırken kaynak fotoğraf kadrajıyla aynı oranı kullan; kapanınca kaydırma konumu değişmesin.',avoid:'Lightbox’a kamera uçuşu ekleme. Kayıtta görünen amaç bir fotoğrafı incelemek; form veya yeni sayfa değil.',refs:[R('era','lightbox','Büyütülen fotoğraf kapanınca aynı detay sütununa dönüyor. Kaynak konumunu koruma ilkesi doğrudan uygun.')]},
 contact:{observation:'Havuz-cephesi fotoğrafı üzerinde fiyat, ev özeti ve viewing formu kâğıt kartta yerleşiyor. Kart evin orta kısmının büyük bölümünü örtüyor.',action:'Kartı mimari odağın daha boş tarafına taşı ya da görseli daha geniş kadrajla tut. Fiyat/özet → form sırası korunmalı; kart yerleşirken görüntü oranını yeniden değiştirme.',avoid:'Form gönderimi kayıtta yapılmıyor; görsel değerlendirmeyi formun çalıştığına dair işlev notu gibi sunma.',refs:[R('era','closing-cta','Kapanışta bir güçlü görsel ve net çağrı yeterli. Angora’da görselin mimari odağını karta feda etme.'),R('likova','map-entry','Bilgi kartı ile arka görselin ayrı okunur alanları var. Bunu contact kadrajına aktar; harita estetiğini kopyalama.')]},
 footerEntry:{observation:'Fotoğraflı viewing sahnesi çıkınca aynı yeşil zeminde beyaz wireframe ve üç eylem linki açılıyor. Dolu fotoğraf ile çizgisel teknik görüntünün görsel yoğunluğu farklı.',action:'Contact kartının çıkışı ile wireframe’in girişini üst üste yığma. Önce yeşil alanı aç, ardından model ve linkleri tek kompozisyon olarak göster; fotoğrafı boş maskeye indirgeme.',avoid:'ERA’nın daralan teras penceresini burada tekrarlamak gerekmiyor. Bu kapanışın özgün malzemesi çizgisel ev.',refs:[R('era','footer','Görüntü daralırken gerçek footer bilgisi onun etrafında kuruluyor. Alınacak şey bilgiyle birlikte kurulan kapanış; kutu biçimi değil.'),R('likova','master-plan','Teknik model ve çağrı aynı sahnede okunuyor. Angora’nın çizgisel modeline uygun bir sade kapanış ilkesi.')]},
 orbit:{observation:'Beyaz çizgisel ev çevresinde görüş açısı değişiyor; sağdaki eylem linkleri sabit kalıyor. Çevre binalar daha silik, ev daha belirgin.',action:'Bu etkileşimi koru. Evin merkezi ve ölçeği sabit kalsın; kenar gradient’i ince çizgileri dengeli söndürsün. Linkler modelle aynı ritimde oynamamalı.',avoid:'Likova’nın dolu modelini veya otomatik orbitini ekleme. Angora’da kontrol edilen çizgisel ev kendi kimliğini taşıyor.',refs:[R('likova','model','Model açısı ile bilgi alanının ayrı rolleri var. Angora’da eylemler sabit kalırken evin çevresinde dönmek bu ayrımı iyi kullanıyor.')]},
 mobileFooter:{observation:'Çizgisel model mobilde eylem linklerinin üstüne yerleşiyor. Aşağı ilerleyince model kadraj dışına çıkar, üç link ve küçük kaynak/credit bilgisi kalıyor.',action:'Modelin tam ev siluetini gösteren yüksekliğini koru; CTA başlığını modelin üzerine taşırma. Linkleri dokunulabilir tek kolon olarak bırak, uzun kaynak notunu görsel kapanıştan ayır.',avoid:'Mobil kayıtta orbit hareketi gösterilmiyor. Desktop etkileşim başarısı mobilde doğrulanmış sayılmaz.',refs:[R('likova','footer','Mobil kapanış eylem ve alt bilgiyi tek dikey hiyerarşide tutuyor. Angora’nın üç linkini bu netlikte bırak.'),R('era','footer','Fotoğraf penceresi ile kapanış bilgisi ayrı alanlarda okunuyor. Angora’da model ile CTA aynı sınırı korumalı.')]},
 finalReverse:{observation:'Wireframe footer’dan contact fotoğrafına, ardından yatay galeriye geri dönülüyor. Galeri tekrar göründüğünde farklı fotoğraflar kadrajda; geçmiş konumun bağını okumak zorlaşıyor.',action:'Footer → contact → galeri dönüşlerinde önceki ray konumunu koru. Düşey devir ile yatay rayı aynı anda oynatma; galeri yerine oturduktan sonra yatay hareket devam etsin.',avoid:'Kayıt hangi gesture/section link yolunun kullanıldığını tamamen göstermiyor; teşhis input motoru değil, görülen yön ve konum sürekliliğidir.',refs:[R('era','footer-reverse','Kapanışın geri okunması aynı sahneye dönüyor. Angora’nın son bölümlerinde aynı kimlik ve ray konumu korunmalı.'),R('likova','video-story','İleri ve geri katmanların aynı görüntü bağlamında kalması, kapanıştan dönüş için uygun kontrol ilkesi.')]}
};

function observedLayers(recipe,device,summary,observation){
 const mobile=device==='mobile';let imageBox=null,textBox=null,maskNote='Kâğıt bölüm zemini devam eder; fotoğraf pencereleri bu zemin içinde ayrı kadrajlar olarak okunur.',uiNote='Üst navigasyon kayıt boyunca görünür; bu çizim onun okuma bölgesini gösterir.';
 if(['opening','camera','heroExit','gardenEntry','gardenChange','gardenReverse','gardenExit'].includes(recipe)){
  imageBox=[0,8,100,92];textBox=mobile?[4,54,92,39]:[4,54,55,39];
  maskNote=recipe==='heroExit'?'Filmin görünür penceresi üstte daralır; kâğıt yüzey alttan devralır. Ev kadrajının bütünlüğü bu eşiğin temel sorunu.':'Fotoğraf/film ekranı doldurur. Caption ve navigasyon önünde; görüntü geçişi ayrı bir sahne değişimidir.';
  uiNote+=' Dış mekân seçimleri/camera durak etiketleri görüntüyle birlikte güncellenir.';
 }
 if(['isoEntry','isoMove','atlasEntry','returnIso'].includes(recipe)){
  imageBox=mobile?[5,9,90,34]:[40,17,57,68];textBox=mobile?[5,43,90,51]:[5,14,33,65];
  maskNote='Teknik sunumun beyaz zemini ve model kadrajı ayrı okunur; bina yönü kat kesitleri boyunca korunur. Fotoğraf cover davranışı değil, bütün model görünümü gereklidir.';
  uiNote+=' Kat tabları seçili kesiti gösterir; metin/fotoğraf durumuyla senkronu ayrıca incelenir.';
 }
 if(['atlasMove','cameraPoint'].includes(recipe)){
  imageBox=mobile?[6,26,88,47]:[5,23,51,71];textBox=mobile?[5,74,90,25]:[58,68,36,26];
  maskNote='Düşük opasiteli üstten kat görüntüsünün önünde bina konturu, oda isimleri ve kamera noktaları var. Katlar yatay ilerler; grafik çizgilerin yeniden oluşması önerilmiyor.';
  uiNote='Kat tabları, numaralı fotoğraf noktaları ve aktif nokta/bakış konisi aynı seçim durumuna bağlı olmalı. Mobilde pinler oda etiketlerini sıkıştırıyor.';
 }
 if(recipe==='map'){
  imageBox=mobile?[0,8,100,56]:[0,8,100,84];textBox=mobile?[4,58,92,36]:[4,32,33,59];
  maskNote='Harita düz resim olarak okunur; yeşil yaşam kartı desktop’ta üstüne, mobilde altına yerleşir. Bu kayıt ayrı harita katmanlarının DOM verisini içermez.';
  uiNote='Ev/Angora sınırı, renkli çevre noktaları ve alttaki legend farklı bilgi görevleri taşır; nokta adları yerine kategoriler okunur.';
 }
 if(['journalEntry','journal','galleryEntry','gallery','kitchenEntry','kitchenMove'].includes(recipe)){
  maskNote='Ortak koyu yeşil zemin fotoğraf ve açıklamayı aynı sahneye bağlar; yeni bir renk maskesi ekleme gereği gözlenmez.';
  imageBox=mobile?[5,32,90,57]:[4,28,92,63];
  if(['gallery','galleryEntry'].includes(recipe))uiNote='Galeri filtreleri, sayaç, önceki/sonraki kontroller ve caption fotoğraf rayını açıklar. Mobilde yalnız ilk fotoğraf ve sonraki kenarı kaydedilmiştir.';
 }
 if(['contact','lightbox'].includes(recipe)){
  maskNote=recipe==='contact'?'Kâğıt viewing kartı havuz fotoğrafının önüne yerleşir. Özellikle mobilde fotoğrafın büyük bölümünü örter.':'Yeşil tam yüzey, büyük fotoğrafı kaynak galeri rayından ayrı bir inceleme penceresinde tutar.';
  imageBox=[0,8,100,92];textBox=recipe==='contact'?(mobile?[5,19,89,74]:[22,22,55,62]):null;
  uiNote=recipe==='contact'?'Fiyat/ev özeti ve form alanları görünür. Kayıtta form gönderilmedi; işlev başarısı puanlanmaz.':'Close kontrolü ve seçili fotoğraf görünür. Kapanışta aynı galeri bağlamı geri gelir.';
 }
 if(['footerEntry','orbit','mobileFooter'].includes(recipe)){
  maskNote='Koyu yeşil zemin süreklidir; wireframe kenarlarında azalan çizgisel yoğunluk görülür. Model ve eylemler ayrı okuma alanlarıdır.';
  imageBox=mobile?[0,8,100,47]:[0,8,53,82];textBox=mobile?[5,42,90,49]:[57,22,36,58];
  uiNote='Arrange a viewing / Explore the 3D residence / View the listing linkleri modelden ayrı kalır. Desktop’ta orbit gösterilir; mobil kayıtta orbit yoktur.';
 }
 return [{type:'image',note:summary,range:[0,1],box:imageBox},{type:'mask',note:maskNote,range:[0,1],box:null},{type:'text',note:observation,range:[0,1],box:textBox},{type:'ui',note:uiNote,range:[0,1],box:[0,0,100,8]}];
}

function cut(key,start,end,title,family,summary,recipe,device,overrides={}){
 const base=recipes[recipe];if(!base)throw Error(`Unknown review recipe: ${recipe}`);
 const review={...base,...overrides};review.references=base.refs.map(r=>({flow:`${r.site}-${device}`,key:r.key,reason:r.reason}));delete review.refs;
 if(device==='desktop')review.references=review.references.map(r=>r.key==='hero-return'?{...r,key:'video-story',reason:'Desktop kaydında ileri–geri yüzeyler aynı film bağlamına dönüyor. Kat kimliğinin de geri dönüşte resetlenmemesi uygun bir çıkarım.'}:r);
 if(device==='mobile'){
 review.references=review.references.map(r=>{
   if(r.key==='pins')return {...r,key:'amenity-tabs',reason:'ERA mobil kaydında hero pinleri gösterilmiyor. Amenity seçiminin vurgusu, fotoğrafı ve açıklaması birlikte değişiyor; Angora kamera pinlerinde aynı durum senkronu kullanılabilir.'};
   if(r.key==='detail-gallery')return {...r,key:'interior-gallery',reason:'Mobilde fotoğraf tek bir galeri penceresinde değişiyor. Angora’nın fotoğraf/caption eşleşmesi için uygun; desktop fotoğraf sütunu burada örnek alınmıyor.'};
   if(r.key==='plan-detail')return {...r,key:'residence-type',reason:'ERA’nın mobil kaydında plan detayına gidilmiyor. Kat adı ve ölçünün modelle birlikte okunması referans alınır; aynı kat iso → plan önerisi bir tasarım çıkarımıdır.'};
   if(recipe==='atlasMove'&&r.key==='horizontal')return {...r,key:'interior-gallery',reason:'Mobilde görsel aynı galeri penceresinde değişiyor. Angora’da plan+fotoğraf tek grup olarak yatay ilerleyebilir; ERA desktop yatay rayı mobilde birebir kopyalanmaz.'};
   if(recipe==='atlasMove'&&r.key==='residence-type')return {...r,reason:'Kat adı, fotoğraf ve alan bilgisi tek kolonda birlikte okunuyor. Angora’nın mobil plan/fotoğraf oranını bu hiyerarşiyle düzelt.'};
   if(recipe==='gallery'&&r.key==='horizontal')return {...r,key:'interior-gallery',reason:'Mobil fotoğraf seçimi gerçek tek pencere galerisine dönüşüyor. Desktop pin’ini dar ekrana taşıma; native yatay gezintiyi koru.'};
   if(recipe==='heroExit'&&r.flow==='era-mobile')return {...r,reason:'Mobil mimari görüntü üstten ayrılırken beyaz bilgi yüzeyi görünür. Angora’da yeni kâğıt zemini görüntünün son duruşuyla birlikte okut.'};
   if(recipe==='camera'&&r.key==='model')return {...r,reason:'Mobil model kadrajı değişirken büyük bilgi altta ayrı bir bölgede kalıyor. Angora’da da kamera varışı ile caption’ı eşleştir; model stilini kopyalama.'};
   if(recipe==='journalEntry'&&r.key==='interior-columns')return {...r,reason:'ERA mobilde iki kolon, tek dikey fotoğraf/açıklama sırasına dönüşüyor. Angora’nın Journal’ında bu uyarlama; karşıt yatay uçuşlardan daha uygun.'};
   if(recipe==='roomMove'&&r.key==='interior-columns')return {...r,reason:'Fotoğraf ve caption tek dikey blok olarak okunuyor. Dar ekranda hızı farklı iki kolon üretme.'};
   return r;
  });
 }
 review.references=review.references.map(r=>{
  const focus=referenceFocus[`${r.flow}:${r.key}`];return focus?{...r,focus:{...focus}}:r;
 });
 const grade=SCENE_GRADES[`active-${device}`]?.[key];
 if(!grade)throw Error(`Missing individual source grade: active-${device}/${key}`);
 Object.assign(review,grade);
 review.score=Math.min(...grade.scores.filter(n=>n!==null));
 review.verdict=review.score<6?'Yeniden ele al':review.score<8?'İncelt':'Koru';
 review.method=GRADING_METHOD.version;
 review.functional=FUNCTIONAL_ISSUES[`active-${device}:${key}`]||{status:'unverified',severity:null,title:'İşlev onayı verilmedi',reason:'Bu sayı görsel kurgu değerlendirmesidir. Koru, tasarım yönünün korunabileceğini söyler; kontrol, geri dönüş, input veya scroll kilidi testinin geçtiğini söylemez.',acceptance:'İlgili kontrol, ileri/geri ziyaret, modal dönüşü ve dar ekran davranışı gerçek arayüzde ayrıca sınanacak.'};
 review.observation=grade.reasons.join(' ');
 review.action=grade.acceptance;
 const duration=+(end-start).toFixed(3);
 const phases=grade.evidence.map(({sourceTime,note})=>[(sourceTime-start)/duration,note,note]);
 return {key,sourceStart:start,sourceEnd:end,title,family,summary,lesson:review.action,review,phases,layers:observedLayers(recipe,device,summary,review.observation)};
}

const d=(key,start,end,title,family,summary,recipe,overrides={})=>cut(key,start,end,title,family,summary,recipe,'desktop',overrides);
const m=(key,start,end,title,family,summary,recipe,overrides={})=>cut(key,start,end,title,family,summary,recipe,'mobile',overrides);
