function flow(device,offset,duration,scenes){return {
 id:`active-${device}`,project:'active',device,offset,duration,fps:60,width:device==='desktop'?1920:426,height:device==='desktop'?1050:636,
 video:`./assets/casestudy2/active/${device}.mp4`,source:'2026-10-05 15-29-15.mp4',viewport:device==='desktop'?'Desktop · 1920 × 1050':'Mobil emülasyon · 459 × 686',
 deviceNote:'web2’nin 05.10.2026 / 15:29 ekran kaydı incelenmiştir. Desktop geniş rayları, mobil tek kolon/pencereleri ayrı puanlandı. Mobil Chrome responsive emülasyonu; fiziksel telefon testi değildir.',
 coverage:device==='desktop'?'Hero’dan wireframe kapanışa bütün gezinti, katların üç ziyareti, plan geçişleri, yatay galeri, bir lightbox ve geri kapanış kaydedilmiş. Tarayıcı çubukları ve devtools kadraj dışında.':'Hero’dan kaynak/credit satırına gezinti, dış mekânda geri–ileri hareketler, üç mutfak, dört iso kat, dört plan ve seçili kamera 3’ün görünümü kaydedilmiş. Incognito hazırlık bölümü çıkarılmıştır.',
 gaps:device==='desktop'?'İlk yükleme/siyah açılış başlangıcı, menü açılışı, planın tüm kamera pinleri, dimensions düğmesi ve form gönderimi gösterilmez. Input motoru gecikmesi bu video ile ölçülemez.':'Menü, oda galerisi swipe’ı, sekiz fotoğrafın tamamı, lightbox, wireframe orbit hareketi ve form gönderimi gösterilmez. Emülasyon fiziksel cihaz davranışını kanıtlamaz.',
 scenes:scenes.map((s,i)=>({...s,id:i+1,start:+(s.sourceStart-offset).toFixed(3),end:+(s.sourceEnd-offset).toFixed(3),duration:+(s.sourceEnd-s.sourceStart).toFixed(3)}))
};}
export const ACTIVE_FLOWS={'active-desktop':flow('desktop',4,106,desktop),'active-mobile':flow('mobile',122,85,mobile)};
